css:
@import url("https://fonts.googleapis.com/css2?family=Marcellus&family=Lato:wght@400;700&display=swap");
:root{--em:#0F3B34;--em2:#17524A;--ch:#D8C3A5;--ch-l:#F5EFE6;--tx:#23302D;--mu:#6A7572;--ln:#E4DED4;--s:"Marcellus",Georgia,serif;--b:"Lato",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.65;color:var(--tx);background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--s);font-weight:400;margin:0;line-height:1.08;color:var(--em)}
.wrap{max-width:1200px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--ch);padding:8px;z-index:99}
:focus-visible{outline:2px solid var(--ch);outline-offset:3px}
.hd{background:var(--em);color:var(--ch);position:sticky;top:0;z-index:40}.nav{display:flex;align-items:center;justify-content:space-between;height:76px}
.logo{font-family:var(--s);font-size:30px;letter-spacing:.18em;text-decoration:none;color:var(--ch)}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0;font-size:15px;letter-spacing:.06em}.menu a{text-decoration:none}.menu a:hover{color:#fff}
.bag{color:var(--ch);text-decoration:none;border:1px solid var(--ch);padding:7px 14px;font-size:14px}
.burger{display:none;background:none;border:1px solid var(--ch);color:var(--ch);padding:6px 10px;cursor:pointer}
.btn{display:inline-flex;align-items:center;justify-content:center;padding:14px 28px;font-family:var(--b);font-weight:700;font-size:14px;letter-spacing:.1em;text-transform:uppercase;text-decoration:none;border:1px solid var(--em);cursor:pointer}
.btn-e{background:var(--em);color:var(--ch)}.btn-e:hover{background:var(--em2)}.btn-l{background:transparent;color:var(--em)}
.hero{background:var(--em);color:#CFDAD6;display:grid;grid-template-columns:1fr 1fr;min-height:600px}
.hero .c{padding:80px 8% 80px max(22px,calc((100vw - 1200px)/2 + 22px));display:flex;flex-direction:column;justify-content:center}
.hero small{letter-spacing:.3em;color:var(--ch);font-size:13px}.hero h1{color:#fff;font-size:clamp(48px,6.4vw,92px);margin:16px 0}
.hero p{font-size:19px;max-width:42ch;margin:0 0 28px}.hero .btn{border-color:var(--ch);background:var(--ch);color:var(--em);align-self:flex-start}
.hero img{width:100%;height:100%;object-fit:cover}
.trust{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid var(--ln)}.trust div{padding:20px;text-align:center;font-size:14px;border-right:1px solid var(--ln)}.trust div:last-child{border:0}.trust b{display:block;font-family:var(--s);font-size:18px;color:var(--em);font-weight:400}
section{padding:90px 0}.head{text-align:center;margin-bottom:36px}.head h2{font-size:clamp(38px,4.6vw,58px)}.head p{color:var(--mu);margin:10px 0 0}
.chips{display:flex;gap:10px;justify-content:center;margin-bottom:30px;flex-wrap:wrap}.chips button{border:1px solid var(--ln);background:#fff;padding:9px 18px;font:inherit;font-size:14px;cursor:pointer;letter-spacing:.05em}
.chips button[aria-pressed=true]{background:var(--em);color:var(--ch);border-color:var(--em)}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}
.p figure{margin:0 0 12px;background:var(--ch-l);aspect-ratio:1/1;overflow:hidden}.p img{width:100%;height:100%;object-fit:cover;transition:transform .5s}.p:hover img{transform:scale(1.05)}
.p small{color:var(--mu);font-size:13px;letter-spacing:.08em;text-transform:uppercase}.p h3{font-size:22px;margin:4px 0}.p b{font-weight:400;font-size:17px}
.p button{margin-top:10px;width:100%;background:none;border:1px solid var(--em);padding:10px;font:inherit;font-size:13px;letter-spacing:.1em;text-transform:uppercase;cursor:pointer;color:var(--em)}.p button:hover{background:var(--em);color:var(--ch)}
.eng{background:var(--ch-l)}.eg{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}
.ring{background:#fff;aspect-ratio:1/1;display:grid;place-items:center;border:1px solid var(--ln)}.ring svg{width:80%;height:auto}
.eg h2{font-size:clamp(36px,4.2vw,54px);margin-bottom:14px}.eg p{color:var(--mu)}
.eg label{display:block;font-weight:700;font-size:14px;margin:18px 0 6px;letter-spacing:.05em}
.eg input,.eg select{width:100%;border:1px solid var(--ln);padding:12px 14px;font:inherit;background:#fff}
.opts{display:flex;gap:10px}.opts button{flex:1;border:1px solid var(--ln);background:#fff;padding:10px;font:inherit;font-size:14px;cursor:pointer}.opts button[aria-pressed=true]{border-color:var(--em);background:var(--em);color:var(--ch)}
.chk{display:flex;gap:10px;align-items:center;margin-top:16px;font-size:15px}.chk input{width:18px;height:18px;accent-color:var(--em)}
.tot{font-family:var(--s);font-size:30px;color:var(--em);margin:18px 0}
.sz table{width:100%;border-collapse:collapse;font-size:15px;max-width:720px;margin:0 auto}.sz th,.sz td{border-bottom:1px solid var(--ln);padding:10px;text-align:center}.sz th{font-family:var(--s);font-weight:400;color:var(--em);font-size:17px}
.tw{overflow-x:auto}
.rv{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.rv blockquote{margin:0;border:1px solid var(--ln);padding:28px}.rv p{font-family:var(--s);font-size:22px;line-height:1.35;color:var(--em)}.rv cite{font-style:normal;font-size:14px;color:var(--mu)}
.faq{max-width:780px;margin:0 auto}.faq details{border-bottom:1px solid var(--ln);padding:16px 0}.faq summary{cursor:pointer;font-family:var(--s);font-size:22px;list-style:none;color:var(--em)}.faq summary::-webkit-details-marker{display:none}.faq p{color:var(--mu);margin:8px 0 0}
footer{background:var(--em);color:#A9BDB7;padding:40px 0;font-size:14px}.ft{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}footer a{color:var(--ch)}
.toast{position:fixed;left:50%;bottom:24px;transform:translate(-50%,120px);background:var(--em);color:var(--ch);padding:12px 22px;transition:.3s;z-index:70;visibility:hidden}.toast.show{transform:translate(-50%,0);visibility:visible}
@media(max-width:980px){.menu{display:none}.burger{display:block}.menu.open{display:flex;flex-direction:column;position:absolute;top:76px;left:0;right:0;background:var(--em);padding:20px;gap:14px}
.hero,.eg{grid-template-columns:1fr}.hero img{height:380px}.grid{grid-template-columns:1fr 1fr}.trust{grid-template-columns:1fr 1fr}.rv{grid-template-columns:1fr}}
@media(max-width:520px){section{padding:64px 0}.grid{gap:14px}}

javascript:
const P=[["Pearl strand necklace","Gold",680,"1515562141207-7a88fb7ce338"],["Fine chain pendant","Gold",240,"1599643478518-a784e5dc4c8f"],["Sapphire drop earrings","Silver",390,"1535632066927-ab7c9ab60908"],["Rose gold tennis bracelet","Rose",520,"1611591437281-460bfbe1220a"],["Everyday gold chain","Gold",190,"1599643478518-a784e5dc4c8f"],["Silver halo earrings","Silver",260,"1535632066927-ab7c9ab60908"],["Rose gold link bracelet","Rose",310,"1611591437281-460bfbe1220a"],["Pearl stud gift set","Silver",150,"1515562141207-7a88fb7ce338"]];
const $=id=>document.getElementById(id);let n=0;const lab={Gold:"Yellow gold",Silver:"Sterling silver",Rose:"Rose gold"};
function toast(t){const x=$('toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}
function grid(m){$('grid').innerHTML=P.filter(p=>m==='all'||p[1]===m).map(p=>`<article class="p"><figure><img src="https://images.unsplash.com/photo-${p[3]}?w=500&h=500&q=75&auto=format&fit=crop" alt="${p[0]}" width="500" height="500" loading="lazy"></figure><small>${lab[p[1]]}</small><h3>${p[0]}</h3><b>£${p[2]}</b><button type="button" data-n="${p[0]}">Add to bag</button></article>`).join('')}
$('chips').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('chips').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));grid(b.dataset.m)};grid('all');
$('grid').onclick=e=>{const b=e.target.closest('[data-n]');if(!b)return;n++;$('bc').textContent=n;toast(b.dataset.n+' added to your bag')};
$('engIn').oninput=e=>{$('engTxt').textContent=e.target.value||' '};
$('metal').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('metal').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));const c=b.dataset.c.split(',');$('g1').setAttribute('stop-color',c[0]);$('g2').setAttribute('stop-color',c[1])};
$('gift').onchange=e=>{$('rp').textContent=e.target.checked?428:420};
$('addRing').onclick=()=>{n++;$('bc').textContent=n;toast('Engraved ring added: "'+($('engIn').value||'no text')+'"')};
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
